import type { CandidateRecord, MediaEra } from '../types.ts';

interface MovieSeedInput {
  name: string;
  industry: string;
  year: number;
  endYear?: number;
  subtitle: string;
  genre: 'action' | 'sci_fi' | 'drama' | 'comedy' | 'thriller' | 'romance' | 'fantasy' | 'crime' | 'horror' | 'animation';
  tone: 'dark' | 'emotional' | 'fun' | 'epic';
  theme:
    | 'space_tech'
    | 'family_bond'
    | 'revenge_justice'
    | 'love_story'
    | 'heist_crime'
    | 'survival_war'
    | 'superhero_power'
    | 'coming_of_age'
    | 'mystery_twist'
    | 'historical_royal'
    | 'sports_underdog'
    | 'friendship_journey';
  franchise: boolean;
  trueStory: boolean;
  blockbuster: boolean;
  awardWinner: boolean;
  leadGender: 'male' | 'female' | 'ensemble';
  mindBending: boolean;
  setting: 'urban_modern' | 'rural_smalltown' | 'historical_period' | 'futuristic_fantasy';
  musicIconic: boolean;
  starTag: string;
  popularity?: number;
  keywords?: string;
}

function getEra(year: number): MediaEra {
  if (year < 1990) return 'classic';
  if (year < 2000) return '90s';
  if (year < 2010) return '2000s';
  if (year < 2020) return '2010s';
  return '2020s';
}

function getDecade(year: number): string {
  const d = Math.floor(year / 10) * 10;
  return `${d}s`;
}

function getPeriodSplit(year: number): string {
  if (year < 2000) return 'pre_2000';
  if (year < 2010) return '2000_2009';
  if (year <= 2016) return '2010_2016';
  return '2017_plus';
}

function slugify(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
}

