export const MOVIE_CANDIDATES: CandidateRecord[] = RAW_MOVIES.map((m) => {
  const era = getEra(m.year);
  const decade = getDecade(m.year);
  return {
    id: `movie_${slugify(m.industry)}_${slugify(m.name)}`,
    category: 'movie',
    industry: m.industry,
    name: m.name,
    subtitle: m.subtitle,
    releaseYear: m.year,
    endYear: m.endYear ?? null,
    decade,
    era,
    popularityPrior: m.popularity ?? 1.0,
    verified: true,
    attributes: {
      genre: m.genre,
      tone: m.tone,
      era,
      before_2010: m.year < 2010 ? 'yes' : 'no',
      period_split: getPeriodSplit(m.year),
      theme: m.theme,
      franchise: m.franchise ? 'yes' : 'no',
      true_story: m.trueStory ? 'yes' : 'no',
      blockbuster: m.blockbuster ? 'yes' : 'no',
      award_winner: m.awardWinner ? 'yes' : 'no',
      lead_gender: m.leadGender,
      mind_bending: m.mindBending ? 'yes' : 'no',
      setting: m.setting,
      music_iconic: m.musicIconic ? 'yes' : 'no',
      star_tag: m.starTag,
      keywords: m.keywords ?? '',
    },
  };
});
